import {type ClassInfo} from 'lit/directives/class-map.js';
import {createElementDirective} from '../shared/directives.js';
import {PSEUDO_CLASSES, isDisabled} from '../shared/pseudo-classes.js';

/** Ripple classes. */
export const RIPPLE_CLASSES = {
  ripple: 'ripple',
  rippleTarget: 'ripple-target',
  rippleHost: 'ripple-host',
  hover: PSEUDO_CLASSES.hover,
  active: PSEUDO_CLASSES.active,
  disabled: PSEUDO_CLASSES.disabled,
};

/** The state provided to the `rippleClasses()` function. */
export interface RippleClassesState {
  /** Emulates `:hover`. */
  hover?: boolean;
  /** Emulates `:active`. */
  active?: boolean;
  /** Emulates `:disabled`. */
  disabled?: boolean;
}

/**
 * Returns the ripple classes to apply to an element based on the given state.
 *
 * @param state The state of the ripple.
 * @return An object of class names and truthy values if they apply.
 */
export function rippleClasses({
  hover = false,
  active = false,
  disabled = false,
}: RippleClassesState = {}): ClassInfo {
  return {
    [RIPPLE_CLASSES.ripple]: true,
    [RIPPLE_CLASSES.hover]: hover,
    [RIPPLE_CLASSES.active]: active,
    [RIPPLE_CLASSES.disabled]: disabled,
  };
}

const MINIMUM_PRESS_MS = 225;
let ripplePropertiesRegistered = false;

/**
 * Sets up ripple functionality for the given element.
 *
 * @param ripple The element on which to set up ripple functionality.
 * @param opts Setup options, supports a cleanup `signal`.
 */
export function setupRipple(
  ripple: HTMLElement,
  opts?: {signal?: AbortSignal},
): void {
  if (
    !ripplePropertiesRegistered &&
    typeof CSS !== 'undefined' &&
    typeof CSS.registerProperty === 'function'
  ) {
    const properties = [
      ['--ripple-scale', '0%'],
      ['--ripple-hover-opacity', '0%'],
      ['--ripple-press-opacity', '0%'],
      ['--ripple-x', '50%'],
      ['--ripple-y', '50%'],
    ];

    try {
      for (const [property, value] of properties) {
        CSS.registerProperty({
          name: property,
          syntax: '<percentage>',
          inherits: false,
          initialValue: value,
        });
      }
    } catch {
      // Ignore errors if the properties are already registered.
    } finally {
      ripplePropertiesRegistered = true;
    }
  }

  // The pressed ripple stays until the press is released AND the circle has
  // finished growing (Compose material3-ripple: the fade out starts after
  // both), so a quick tap still shows the full expansion.
  let holdTimeoutId: number | undefined;
  let pressStart = 0;
  let pressing = false;

  const removeActive = () => {
    clearTimeout(holdTimeoutId);
    holdTimeoutId = undefined;
    ripple.classList.remove(RIPPLE_CLASSES.active);
  };

  const activateRipple = () => {
    // If the ripple is already active, restart the current press animation.
    if (ripple.classList.contains(RIPPLE_CLASSES.active)) {
      for (const animation of ripple.getAnimations()) {
        if (
          (animation as Partial<CSSAnimation>).animationName?.startsWith(
            'ripple-press',
          )
        ) {
          animation.cancel();
          animation.play();
        }
      }
    }

    ripple.classList.add(RIPPLE_CLASSES.active);
    clearTimeout(holdTimeoutId);
    holdTimeoutId = undefined;
    pressing = true;
    pressStart = performance.now();
  };

  const releaseRipple = () => {
    if (!pressing) return;
    pressing = false;
    clearTimeout(holdTimeoutId);
    const remaining = MINIMUM_PRESS_MS - (performance.now() - pressStart);
    if (remaining <= 0) {
      removeActive();
    } else {
      holdTimeoutId = window.setTimeout(removeActive, remaining);
    }
  };

  // Keyboard activation (Space and Enter) shows the same pressed ripple from
  // the center. The click that follows is not a second press.
  let keyPressed = false;
  const pressesWithKey = (event: KeyboardEvent) => {
    if (event.key !== ' ' && event.key !== 'Enter') return false;
    const target = event.target as Element | null;
    return !target?.closest?.(
      'input:not([type=button],[type=checkbox],[type=radio],[type=submit],[type=reset]),textarea,select,[contenteditable]:not([contenteditable=false])',
    );
  };

  // Return true if the ripple is disabled, or if the ripple class has been
  // removed. This allows components to disable and re-enable ripple behavior.
  const isRippleDisabled = () =>
    isDisabled(ripple) || !ripple.matches(`.${RIPPLE_CLASSES.ripple}`);

  ripple.addEventListener(
    'pointerdown',
    (event: PointerEvent): void => {
      if (isRippleDisabled()) return;
      // Set ripple position to the pointer position.
      const rect = ripple.getBoundingClientRect();
      const x = (event.clientX - rect.x) / rect.width;
      const y = (event.clientY - rect.y) / rect.height;
      ripple.style.setProperty('--ripple-x', `${x * 100}%`);
      ripple.style.setProperty('--ripple-y', `${y * 100}%`);
      activateRipple();
      // The press can end anywhere, also outside the ripple.
      const release = () => {
        window.removeEventListener('pointerup', release);
        window.removeEventListener('pointercancel', release);
        releaseRipple();
      };
      window.addEventListener('pointerup', release);
      window.addEventListener('pointercancel', release);
      opts?.signal?.addEventListener('abort', release, {once: true});
    },
    opts,
  );

  ripple.addEventListener(
    'keydown',
    (event: KeyboardEvent): void => {
      // Reset ripple pointer position when a key is pressed.
      ripple.style.removeProperty('--ripple-x');
      ripple.style.removeProperty('--ripple-y');
      if (event.repeat || isRippleDisabled() || !pressesWithKey(event)) return;
      keyPressed = true;
      activateRipple();
    },
    opts,
  );

  ripple.addEventListener(
    'keyup',
    (event: KeyboardEvent): void => {
      if (!keyPressed || !pressesWithKey(event)) return;
      releaseRipple();
      // Space clicks after its keyup: let that click pass first.
      setTimeout(() => (keyPressed = false));
    },
    opts,
  );

  ripple.addEventListener(
    'blur',
    () => {
      if (keyPressed) {
        keyPressed = false;
        releaseRipple();
      }
    },
    {...opts, capture: true},
  );

  ripple.addEventListener(
    'click',
    (event) => {
      // A UIEvent.detail click count of 0 indicates the click was not triggered
      // by a pointer. Show the ripple press effect for these clicks as well.
      if (event.detail === 0 && !keyPressed && !isRippleDisabled()) {
        activateRipple();
        releaseRipple();
      }
    },
    opts,
  );
}

/**
 * A Lit directive that adds updates the position of a ripple to match pointer
 * interactions. Use with the `.ripple` class.
 *
 * @example
 * ```ts
 * class Component extends LitElement {
 *   static styles = [rippleStyles, css`...`];
 *
 *   render() {
 *     return html`<button class="ripple" ${ripple()}>Ripple effect</button>`;
 *   }
 * }
 * ```
 *
 * Use the `.ripple-target` class if the interactive element is a parent or
 * child of the ripple element.
 *
 * The `ripple()` directive should be applied to the parent element, which may
 * be the `.ripple-target` instead of the `.ripple`.
 *
 * @example
 * ```ts
 * html`
 *   <div class="card ripple" ${ripple()}>
 *     Child interactive element
 *     <button class="ripple-target card-btn"></button>
 *   </div>
 *
 *   <button class="ripple-target" ${ripple()}>
 *     Parent interactive element
 *     <span class="ripple"></span>
 *   </button>
 * `;
 * ```
 */
export const ripple = createElementDirective(setupRipple);
